/** Returns the order total for a given subtotal. */
public BigDecimal total(BigDecimal subtotal) {
    return subtotal;
}

public BigDecimal applyCoupon(BigDecimal subtotal, String code) {
    if ("SAVE5".equals(code)) {
        BigDecimal result = subtotal.subtract(new BigDecimal("5.00"));
        if (result.compareTo(BigDecimal.ZERO) < 0) {
            return new BigDecimal("0.00");
        }
        return result;
    }
    return subtotal;
}

